import{_ as s,o as a,c as i,a4 as e}from"./chunks/framework.BBs01uty.js";const c=JSON.parse('{"title":"06 · RAG 评估体系设计","description":"","frontmatter":{},"headers":[],"relativePath":"project-architecture/06-evaluation.md","filePath":"project-architecture/06-evaluation.md"}'),n={name:"project-architecture/06-evaluation.md"};function o(r,t,l,d,h,p){return a(),i("div",null,[...t[0]||(t[0]=[e(`<h1 id="_06-·-rag-评估体系设计" tabindex="-1">06 · RAG 评估体系设计 <a class="header-anchor" href="#_06-·-rag-评估体系设计" aria-label="Permalink to &quot;06 · RAG 评估体系设计&quot;">​</a></h1><blockquote><p>这篇讲清一件事：<strong>怎么衡量&quot;检索准不准、回答好不好&quot;</strong>。 评估是优化的前提——没有它，所有改动都只能靠感觉。</p></blockquote><h2 id="一、为什么必须先有评估" tabindex="-1">一、为什么必须先有评估 <a class="header-anchor" href="#一、为什么必须先有评估" aria-label="Permalink to &quot;一、为什么必须先有评估&quot;">​</a></h2><p>这个项目最典型的一课：早期评估只有 12 道题、只看&quot;命中率&quot;，结果 <strong>12 题全是 100%</strong>。指标饱和了——无论怎么改检索、换不换模型，数字都不变，<strong>根本测不出好坏</strong>。</p><p>所以顺序必须是：<strong>先把评估做对，再谈优化</strong>。评估集就是&quot;优化这件事的度量衡&quot;。</p><h2 id="二、两层评估" tabindex="-1">二、两层评估 <a class="header-anchor" href="#二、两层评估" aria-label="Permalink to &quot;二、两层评估&quot;">​</a></h2><p>RAG 的链路长，一个改动可能只影响其中一段，所以要分两层测：</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Q[用户问题] --&gt; R[检索层&lt;br/&gt;捞到对的资料了吗?]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  R --&gt; G[生成层&lt;br/&gt;基于资料答得好吗?]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  R -.-&gt;|检索层评估| M1[&quot;Hit@k / Top1 / Recall@k / MRR&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  G -.-&gt;|生成层评估| M2[&quot;忠实度 / 完整性 / 引用准确性&quot;]</span></span></code></pre></div><p><strong>关键认知：检索好 ≠ 回答好。</strong> 本项目实测过——检索层 Hit@5 已经 100%，但生成层照样发现&quot;模型没检索就编造引用&quot;的问题。<strong>只看检索会漏掉一半的问题。</strong></p><table tabindex="0"><thead><tr><th>层</th><th>脚本</th><th>回答的问题</th><th>耗时</th></tr></thead><tbody><tr><td>检索层</td><td><code>pnpm kb eval</code></td><td>期望文档能不能被捞出来、排第几</td><td>~30 秒</td></tr><tr><td>生成层</td><td><code>pnpm kb eval --full</code></td><td>回答是否忠实、完整、引用是否准确</td><td>~14 分钟</td></tr></tbody></table><h2 id="三、检索层设计-rag-eval-ts" tabindex="-1">三、检索层设计（<code>rag-eval.ts</code>） <a class="header-anchor" href="#三、检索层设计-rag-eval-ts" aria-label="Permalink to &quot;三、检索层设计（\`rag-eval.ts\`）&quot;">​</a></h2><h3 id="_3-1-数据集" tabindex="-1">3.1 数据集 <a class="header-anchor" href="#_3-1-数据集" aria-label="Permalink to &quot;3.1 数据集&quot;">​</a></h3><p>数据<strong>独立存放</strong>在 <code>eval/retrieval-cases.json</code>——<strong>数据与评估逻辑分离</strong>，加题/改题只改数据、不碰代码，也便于 diff 和多人维护。</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> EvalCase</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">q</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">expect</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[]; </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">category</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><ul><li><strong><code>expect</code> 是数组</strong>：一个问题可能多篇文档都算对（如&quot;Vue 响应式&quot;对应 3 篇）。</li><li><strong><code>category</code> 用于分层</strong>：覆盖 React / Vue / 浏览器 / JS / CSS / 性能 / 工程化 / 服务端 / AI Agent / 算法 / 大前端 共 11 类、<strong>250 题</strong>。</li><li><strong>刻意加&quot;难例&quot;</strong>：跨文档问题（对比 React/Vue 响应式）、相似文档区分（<code>monitoring</code> vs <code>error-monitoring</code>）。</li></ul><h3 id="_3-2-指标-一个排名-派生四个视角" tabindex="-1">3.2 指标：一个排名，派生四个视角 <a class="header-anchor" href="#_3-2-指标-一个排名-派生四个视角" aria-label="Permalink to &quot;3.2 指标：一个排名，派生四个视角&quot;">​</a></h3><p>核心只需要算一个值——<strong>期望文档在结果里最早出现的排名</strong>：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rankOf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">sources</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[], </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">expect</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[], </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">k</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> number</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 精确匹配（不是子串），返回最佳命中排名 + topK 内命中的期望文档数</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>由它派生四个指标，各自回答<strong>不同的问题</strong>：</p><h4 id="_1-hit-5-——-至少捞到一篇了吗-最宽松" tabindex="-1">① Hit@5 —— &quot;至少捞到一篇了吗&quot;（最宽松） <a class="header-anchor" href="#_1-hit-5-——-至少捞到一篇了吗-最宽松" aria-label="Permalink to &quot;① Hit@5 —— &quot;至少捞到一篇了吗&quot;（最宽松）&quot;">​</a></h4><ul><li><strong>算法</strong>：<code>排名 &gt; 0</code> 的题数 ÷ 总题数</li><li><strong>含义</strong>：期望文档里<strong>任意一篇</strong>进了前 5，这题就算通过</li><li><strong>示例</strong>：某题期望 <code>javascript/closure.md</code>，检索结果第 3 名命中 → <strong>Hit@5 记 1（通过）</strong></li><li><strong>盲区</strong>：只要&quot;沾边就算过&quot;，看不出排得准不准、也看不出多篇捞全没捞全</li></ul><h4 id="_2-hit-1-——-排第一了吗-严格" tabindex="-1">② Hit@1 —— &quot;排第一了吗&quot;（严格） <a class="header-anchor" href="#_2-hit-1-——-排第一了吗-严格" aria-label="Permalink to &quot;② Hit@1 —— &quot;排第一了吗&quot;（严格）&quot;">​</a></h4><ul><li><strong>算法</strong>：<code>排名 = 1</code> 的题数 ÷ 总题数</li><li><strong>含义</strong>：期望文档必须<strong>排在第一位</strong></li><li><strong>示例</strong>：上例期望文档排第 3 → <strong>Hit@1 记 0（不通过）</strong></li><li><strong>为什么必须有它</strong>：比 Hit@5 严格得多，反映<strong>排序质量</strong>。本项目实测中，同一套检索 <strong>Hit@5 长期 98~100%</strong>，而 Hit@1 从 58% 一路涨到 89.6%——<strong>只有它才看得出优化效果</strong></li></ul><h4 id="_3-recall-5-——-该捞的捞全了吗-多篇场景-最严格" tabindex="-1">③ Recall@5 —— &quot;该捞的捞全了吗&quot;（多篇场景，最严格） <a class="header-anchor" href="#_3-recall-5-——-该捞的捞全了吗-多篇场景-最严格" aria-label="Permalink to &quot;③ Recall@5 —— &quot;该捞的捞全了吗&quot;（多篇场景，最严格）&quot;">​</a></h4><ul><li><strong>算法</strong>：每题 <code>top5 内命中的期望文档数 ÷ 期望文档总数</code>，再对所有题取平均</li><li><strong>含义</strong>：衡量<strong>覆盖率</strong>——当一道题的答案散落在多篇文档时，捞到了几成</li><li><strong>示例（关键）</strong>：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>expect（3 篇）: vue/reactive.md, vue/primitive-reactive.md, vue/double-binding.md</span></span>
<span class="line"><span>检索 top5    : [reactive.md, primitive-reactive.md, 其他A, 其他B, 其他C]</span></span>
<span class="line"><span>→ 命中 2 / 期望 3 → Recall@5 = 0.667</span></span></code></pre></div><ul><li><strong>它的独特价值</strong>：这条题 <code>Hit@5 = 1</code>（捞到了）、<code>Hit@1 = 1</code>（还排第一）——<strong>只有 Recall@5 暴露出&quot;3 篇只捞到 2 篇&quot;</strong>。本项目实测 Recall@5 长期停在 0.96 左右（混合检索后 0.983），就是这么发现的</li></ul><h4 id="_4-mrr-——-整体排得靠不靠前" tabindex="-1">④ MRR —— &quot;整体排得靠不靠前&quot; <a class="header-anchor" href="#_4-mrr-——-整体排得靠不靠前" aria-label="Permalink to &quot;④ MRR —— &quot;整体排得靠不靠前&quot;&quot;">​</a></h4><ul><li><strong>算法</strong>：<code>MRR = (1/N) × Σ(1/rankᵢ)</code>，<code>rankᵢ</code> 是第 i 题的命中排名（未命中记 0）</li><li><strong>含义</strong>：排名越靠前贡献越大（第 1 名得 1 分、第 2 名 0.5、第 3 名 0.33…）</li><li><strong>示例</strong>：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第 1 题 rank=1 → 1/1 = 1.0</span></span>
<span class="line"><span>第 2 题 rank=2 → 1/2 = 0.5</span></span>
<span class="line"><span>第 3 题 rank=5 → 1/5 = 0.2</span></span>
<span class="line"><span>第 4 题 未命中  → 0</span></span>
<span class="line"><span>MRR = (1.0 + 0.5 + 0.2 + 0) / 4 = 0.425</span></span></code></pre></div><ul><li><strong>它的价值</strong>：Hit 类只区分&quot;中/不中&quot;，MRR 能区分&quot;<strong>中得靠不靠前</strong>&quot;——第 1 名和第 5 名在 Hit@5 里都是 1，但 MRR 分别是 <strong>1.0</strong> 和 <strong>0.2</strong></li></ul><h4 id="为什么四个都要-互为补充" tabindex="-1">为什么四个都要（互为补充） <a class="header-anchor" href="#为什么四个都要-互为补充" aria-label="Permalink to &quot;为什么四个都要（互为补充）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>指标</th><th>严格度</th><th>盲区</th></tr></thead><tbody><tr><td>Hit@5</td><td>最宽</td><td>排序质量、覆盖率都看不出</td></tr><tr><td>Hit@1</td><td>严</td><td>多篇场景覆盖不全看不出</td></tr><tr><td>Recall@5</td><td>最严（覆盖）</td><td>只看覆盖，不看排序</td></tr><tr><td>MRR</td><td>中</td><td>不区分覆盖几篇，只看最佳排名</td></tr></tbody></table><blockquote><p>本项目正是靠这四个的组合，分别发现了&quot;<strong>面试题污染</strong>&quot;（Hit@1 偏低）和&quot;<strong>多篇覆盖不全</strong>&quot;（Recall@5 偏低）——<strong>两种性质完全不同的问题</strong>。</p></blockquote><h3 id="_3-3-匹配策略-精确-部分分" tabindex="-1">3.3 匹配策略：精确 + 部分分 <a class="header-anchor" href="#_3-3-匹配策略-精确-部分分" aria-label="Permalink to &quot;3.3 匹配策略：精确 + 部分分&quot;">​</a></h3><ul><li><strong>精确路径匹配</strong>：用 <code>===</code>（配合路径规范化），而不是 <code>includes</code> 子串——避免 <code>xxx/react/concept.md</code> 被 <code>react/concept.md</code> 误判命中。</li><li><strong>多篇期望给部分分</strong>：<code>Recall@k</code> 天然支持&quot;命中 2/3 篇&quot;得 0.67，比&quot;全有或全无&quot;更细腻。</li></ul><h3 id="_3-4-分类统计-定位弱项" tabindex="-1">3.4 分类统计：定位弱项 <a class="header-anchor" href="#_3-4-分类统计-定位弱项" aria-label="Permalink to &quot;3.4 分类统计：定位弱项&quot;">​</a></h3><p>输出按 <code>category</code> 分组，一眼看出哪个主题是短板：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器：22 题 | Hit@5 100% | Hit@1 86% | Recall@5 0.970 | MRR 0.932</span></span>
<span class="line"><span>JavaScript：17 题 | Hit@5 100% | Hit@1 82% | Recall@5 1.000 | MRR 0.892</span></span>
<span class="line"><span>CSS：14 题 | Hit@5 100% | Hit@1 86% | Recall@5 0.952 | MRR 0.917</span></span>
<span class="line"><span>服务端：46 题 | Hit@5 100% | Hit@1 91% | Recall@5 0.993 | MRR 0.957</span></span>
<span class="line"><span>AI Agent：31 题 | Hit@5 100% | Hit@1 100% | Recall@5 1.000 | MRR 1.000</span></span>
<span class="line"><span>...</span></span></code></pre></div><blockquote><p>实际就是这么发现 <strong>JS / 性能的 Hit@1 偏低</strong>（答案排不到第一）的——按主题分组后，短板一目了然。</p></blockquote><h3 id="_3-5-数据集怎么扩充-脚本生成-人工审核" tabindex="-1">3.5 数据集怎么扩充：脚本生成 + 人工审核 <a class="header-anchor" href="#_3-5-数据集怎么扩充-脚本生成-人工审核" aria-label="Permalink to &quot;3.5 数据集怎么扩充：脚本生成 + 人工审核&quot;">​</a></h3><p>样本量是评估可信度的地基，但手动出题慢。所以提供了一个生成脚本：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cases:gen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --limit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 用本地 LLM 逐篇文档生成&quot;能由它回答的问题&quot;</span></span></code></pre></div><p>它遍历文档、让模型基于内容出一个问题，产出 <code>eval/retrieval-cases.generated.json</code> 作为<strong>初稿</strong>。</p><p><strong>但必须人工审核</strong>——实测生成结果里混进了 <code>index.md</code>、<code>GUIDE.md</code> 这类<strong>项目说明文档</strong>（不属于技术知识，不该进评估集）；措辞、期望文档的准确性也要人工过一遍。审核通过后再合并进 <code>retrieval-cases.json</code>。</p><h2 id="四、生成层设计-rag-gen-eval-ts" tabindex="-1">四、生成层设计（<code>rag-gen-eval.ts</code>） <a class="header-anchor" href="#四、生成层设计-rag-gen-eval-ts" aria-label="Permalink to &quot;四、生成层设计（\`rag-gen-eval.ts\`）&quot;">​</a></h2><h3 id="_4-1-评估维度" tabindex="-1">4.1 评估维度 <a class="header-anchor" href="#_4-1-评估维度" aria-label="Permalink to &quot;4.1 评估维度&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>含义</th></tr></thead><tbody><tr><td><strong>忠实度</strong></td><td>回答是否完全基于检索到的资料，有无编造</td></tr><tr><td><strong>完整性</strong></td><td>是否真正回答了问题</td></tr><tr><td><strong>引用准确性</strong></td><td><code>[来源N]</code> 标注是否恰当、编号是否有效</td></tr></tbody></table><h3 id="_4-2-判定方式-自动检查-llm-打分-可人工复核" tabindex="-1">4.2 判定方式：自动检查 + LLM 打分 + 可人工复核 <a class="header-anchor" href="#_4-2-判定方式-自动检查-llm-打分-可人工复核" aria-label="Permalink to &quot;4.2 判定方式：自动检查 + LLM 打分 + 可人工复核&quot;">​</a></h3><p>三层结合，各司其职：</p><ol><li><strong>自动检查（确定性的，最可靠）</strong><ul><li><strong>引用合法性</strong>：回答里的 <code>[来源N]</code>，编号是否都在 <code>1..来源数</code> 范围内</li><li><strong>拒答检测</strong>：负例题是否如实说&quot;没有/未找到/无法提供&quot;</li></ul></li><li><strong>LLM-as-judge</strong>：用本地 <code>qwen3:8b</code> 按 rubric 给三项各打 1~5 分（输出 JSON） <ul><li>局限：8B 模型自评可能不够客观，需人工校准</li></ul></li><li><strong>人工复核</strong>：脚本把&quot;问题 + 检索来源 + 回答 + 评分&quot;写进 <code>data/gen-eval-report.md</code>，人工过一遍</li></ol><h3 id="_4-3-负例题-专门测-不知道就说不知道" tabindex="-1">4.3 负例题：专门测&quot;不知道就说不知道&quot; <a class="header-anchor" href="#_4-3-负例题-专门测-不知道就说不知道" aria-label="Permalink to &quot;4.3 负例题：专门测&quot;不知道就说不知道&quot;&quot;">​</a></h3><p>这是<strong>测幻觉的关键设计</strong>。评估集里放了几道<strong>知识库答不了</strong>的题：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">q</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;今天上海的天气怎么样？&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">category</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;知识库外(负例)&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">expectAnswer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">q</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;请介绍一下 Kubernetes 的 Pod 调度机制&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">category</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;知识库外(负例)&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">expectAnswer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">q</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;2025 年世界杯冠军是谁？&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">category</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;知识库外(负例)&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">expectAnswer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span></code></pre></div><p>对这类题，<strong>正确的行为是&quot;如实说知识库没有&quot;</strong>，而不是硬答。脚本用关键词（没有/未找到/无法提供…）粗判，人工复核。</p><h2 id="五、评估体系的演进-实战顺序" tabindex="-1">五、评估体系的演进（实战顺序） <a class="header-anchor" href="#五、评估体系的演进-实战顺序" aria-label="Permalink to &quot;五、评估体系的演进（实战顺序）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>做了什么</th><th>发现了什么</th></tr></thead><tbody><tr><td>① 12 题 + Top5</td><td>最初的评估</td><td><strong>指标饱和</strong>（全 100%），什么都测不出</td></tr><tr><td>② 扩到 50 题 + 分层</td><td>按主题铺开</td><td>暴露弱项（Vue/CSS 的 Recall 低），且校准了 1 条错标</td></tr><tr><td>③ 匹配改严</td><td>精确匹配 + Recall@5</td><td>发现&quot;多篇期望覆盖不全&quot;是真实短板</td></tr><tr><td>④ 加生成层评估</td><td>端到端 + 负例题</td><td><strong>发现&quot;无检索却编造引用&quot;</strong>（检索层完全看不到）</td></tr><tr><td>⑤ LLM 出题扩到 250 题</td><td><code>kb cases:gen</code> + 人工审核</td><td>样本量上来后，单题噪声被摊薄，结论才可信</td></tr><tr><td>⑥ 混合检索</td><td>向量 + BM25</td><td><strong>修掉全部&quot;精确词漏召&quot;</strong>（Hit@5 98.4% → 100%）——原理与实现见 <a href="./03-server-rag.html">03 · 后端与 RAG 检索</a></td></tr></tbody></table><p>每一步都在&quot;上一层的盲区&quot;里——这就是为什么要<strong>分层</strong>。</p><h2 id="六、实战收获" tabindex="-1">六、实战收获 <a class="header-anchor" href="#六、实战收获" aria-label="Permalink to &quot;六、实战收获&quot;">​</a></h2><table tabindex="0"><thead><tr><th>发现</th><th>哪一层发现的</th><th>修复</th></tr></thead><tbody><tr><td>面试题污染检索</td><td>检索层</td><td>索引时排除（Hit@1 58% → 75%）</td></tr><tr><td>多篇期望覆盖不全</td><td>检索层（Recall@5）</td><td>混合检索后 0.964 → <strong>0.983</strong></td></tr><tr><td><strong>精确词漏召</strong>（FMP/LCP、&quot;代码审查&quot;这类）</td><td>检索层（Hit@5 未命中，配合逐条实测）</td><td><strong>混合检索</strong> → 4 条未命中全部命中，Hit@5 98.4% → <strong>100%</strong></td></tr><tr><td><strong>无检索却编造引用</strong></td><td><strong>生成层</strong></td><td>Prompt 强化&quot;先检索才能标引用&quot;（引用合法性 4/10 → <strong>10/10</strong>）</td></tr><tr><td>拒答检测误报</td><td>生成层（自动检查）</td><td>补齐正则（&quot;无法提供&quot;等；后来又因&quot;无法<strong>实时</strong>获取&quot;漏判放宽为匹配&quot;无法&quot;）</td></tr></tbody></table><blockquote><p>最有教育意义的是&quot;无检索却编造引用&quot;这条：<strong>检索指标一片绿，生成层却发现了最严重的问题。</strong> 反过来也一样——<strong>只看生成层会漏掉检索漏召</strong>：生成层的忠实度/完整性分数一直很高， 但它不会告诉你&quot;最该被检索到的那篇压根没进来&quot;。所以两层都要跑。</p></blockquote><h3 id="当前基线-250-题" tabindex="-1">当前基线（250 题） <a class="header-anchor" href="#当前基线-250-题" aria-label="Permalink to &quot;当前基线（250 题）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>数值</th></tr></thead><tbody><tr><td>Hit@5</td><td><strong>100.0%</strong></td></tr><tr><td>Hit@1</td><td><strong>89.6%</strong></td></tr><tr><td>Recall@5</td><td><strong>0.983</strong></td></tr><tr><td>MRR</td><td><strong>0.944</strong></td></tr></tbody></table><blockquote><p>Hit@5 已经饱和（100%），<strong>后续优化要改看 Hit@1 / MRR / Recall@5</strong>——这也是为什么一开始就要把四个指标都留着。</p></blockquote><h2 id="七、自动化-怎么防止退化" tabindex="-1">七、自动化：怎么防止退化 <a class="header-anchor" href="#七、自动化-怎么防止退化" aria-label="Permalink to &quot;七、自动化：怎么防止退化&quot;">​</a></h2><p>评估做完要能<strong>持续跑</strong>。目标是：<strong>一条命令跑回归，指标跌破底线就报错</strong>。</p><h3 id="为什么要持续跑-——-检索应该很稳定-这个假设需要被验证" tabindex="-1">为什么要持续跑？——&quot;检索应该很稳定&quot;这个假设需要被验证 <a class="header-anchor" href="#为什么要持续跑-——-检索应该很稳定-这个假设需要被验证" aria-label="Permalink to &quot;为什么要持续跑？——&quot;检索应该很稳定&quot;这个假设需要被验证&quot;">​</a></h3><p>直觉上，知识库就是一堆文档，往里加内容似乎不该让检索变差。<strong>这个假设本身要用数据验证</strong>。实测下来至少三类变化会让指标动：</p><table tabindex="0"><thead><tr><th>变化</th><th>例子（本项目实测）</th></tr></thead><tbody><tr><td><strong>内容增长</strong></td><td>新增一篇相似文档，会把原本排第一的挤下去。这是真实发生过的：cluster 那道题的期望文档被 <code>node-core</code> 抢占</td></tr><tr><td><strong>改配置 / 改代码</strong></td><td>切分参数、混合检索权重、rerank 开关、Prompt。调优时把 BM25 的融合权重从等权（1.0）降到 0.3，Hit@1 就从 86.4% 回到 89.6%——<strong>差 3 个百分点</strong></td></tr><tr><td><strong>换模型</strong></td><td>换 embedding → 向量空间完全变了，必须重建索引；指标也不能与历史直接比（所以记录里带环境指纹）</td></tr></tbody></table><p>所以持续跑的目的不是&quot;修退化&quot;，而是把**&quot;我觉得没变差&quot;变成&quot;数据证明没变差&quot;<strong>。 而且阈值是</strong>底线**不是目标（Hit@1 ≥ 80%，当前 89.6%，留了近 10 个点的余量）：不要求每次都涨，只在跌破底线时拦住。</p><blockquote><p>这是<strong>基座侧</strong>的工程实践，用来校准检索与回答质量。实例使用者不需要自己准备测试集，也不用跑。</p></blockquote><blockquote><p>前提：评估依赖本地 Ollama + Chroma，所以 <strong>CI 跑不了</strong>（除非改用云端 API，违背&quot;本地零成本&quot;）。方案落在<strong>本地命令 + 留档</strong>。</p></blockquote><h3 id="三个命令" tabindex="-1">三个命令 <a class="header-anchor" href="#三个命令" aria-label="Permalink to &quot;三个命令&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>做什么</th><th>耗时</th></tr></thead><tbody><tr><td><code>pnpm test:rag</code></td><td>检索评估 + 对比 + 阈值门禁</td><td>~30 秒</td></tr><tr><td><code>pnpm test:rag:full</code></td><td>再加生成层评估</td><td>~15 分钟</td></tr><tr><td><code>pnpm test:rag:baseline</code></td><td>把当前成绩固化为基线</td><td>秒级</td></tr></tbody></table><h3 id="三份数据-角色不同" tabindex="-1">三份数据，角色不同 <a class="header-anchor" href="#三份数据-角色不同" aria-label="Permalink to &quot;三份数据，角色不同&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文件</th><th>角色</th><th>说明</th></tr></thead><tbody><tr><td><code>eval/thresholds.json</code></td><td><strong>硬底线</strong></td><td>跌破即 <code>exit 1</code>（数值可调，不用改代码）</td></tr><tr><td><code>data/eval-history.jsonl</code></td><td><strong>流水账</strong></td><td>每次运行追加一行 → 支持&quot;较上次&quot;与长期趋势</td></tr><tr><td><code>data/eval-baseline.json</code></td><td><strong>参考靶子</strong></td><td>被认可的某次成绩 → 回答&quot;现在离达标版差多少&quot;</td></tr></tbody></table><p>三者互补：<strong>阈值管&quot;不许退化到底线以下&quot;，基线管&quot;和认可的那版比差多少&quot;，历史管&quot;最近一路怎么走的&quot;</strong>。</p><blockquote><p>记录里带<strong>环境指纹</strong>（embedding 模型、题数等）——换了模型或重建索引后，不同环境的数据不可直接比。</p></blockquote><h3 id="阈值-可在-thresholds-json-调整" tabindex="-1">阈值（可在 <code>thresholds.json</code> 调整） <a class="header-anchor" href="#阈值-可在-thresholds-json-调整" aria-label="Permalink to &quot;阈值（可在 \`thresholds.json\` 调整）&quot;">​</a></h3><blockquote><p>阈值是&quot;<strong>底线</strong>&quot;而不是&quot;目标&quot;，要留余量（当前 Hit@1 89.6%，底线 80%）。</p></blockquote><table tabindex="0"><thead><tr><th>层</th><th>指标</th><th>阈值</th><th>当前值</th></tr></thead><tbody><tr><td>检索</td><td>Hit@1</td><td>≥ 80%</td><td>89.6%</td></tr><tr><td>检索</td><td>Recall@5</td><td>≥ 88%</td><td>98.3%</td></tr><tr><td>检索</td><td>MRR</td><td>≥ 85%</td><td>94.4%</td></tr><tr><td>生成</td><td>引用合法性</td><td>= 100%</td><td>100%</td></tr><tr><td>生成</td><td>忠实度均分</td><td>≥ 4.0</td><td>4.90</td></tr></tbody></table><h3 id="实际输出" tabindex="-1">实际输出 <a class="header-anchor" href="#实际输出" aria-label="Permalink to &quot;实际输出&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>==== 对比 ====</span></span>
<span class="line"><span>较上次：Hit@5 100% (↑2%) | Hit@1 90% (↑2%) | Recall@5 98% (↑2%) | MRR 94% (↑2%)</span></span>
<span class="line"><span>较基线：Hit@5 100% (↑2%) | Hit@1 90% (↑2%) | Recall@5 98% (↑2%) | MRR 94% (↑2%)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>✅ 阈值门禁通过（retrieval）</span></span></code></pre></div><p>跌破底线时：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>❌ 阈值门禁未通过（retrieval）：</span></span>
<span class="line"><span>   - Hit@1: 94% &lt; 要求 99%</span></span></code></pre></div><p>脚本会<strong>非零退出</strong>，因此可以接入任何自动化流程（hook、脚本、将来的 CI）。</p><h3 id="建议的使用节奏" tabindex="-1">建议的使用节奏 <a class="header-anchor" href="#建议的使用节奏" aria-label="Permalink to &quot;建议的使用节奏&quot;">​</a></h3><ol><li>改完检索逻辑 / prompt → <code>pnpm test:rag</code>（快）</li><li>结果满意 → <code>pnpm test:rag:baseline</code> 固化为新基线</li><li>大改动（换模型、改索引）→ <code>pnpm test:rag:full</code></li></ol><h2 id="八、局限与后续" tabindex="-1">八、局限与后续 <a class="header-anchor" href="#八、局限与后续" aria-label="Permalink to &quot;八、局限与后续&quot;">​</a></h2><ul><li><strong>样本量</strong>：250 题已经够用，但<strong>单题差异仍有噪声</strong>（1 题 ≈ 0.4pp），结论别基于一两道题的涨跌；</li><li><strong>LLM judge 自评偏差</strong>：用同一个 8B 模型评自己，可能偏乐观，需人工校准；</li><li><strong>文件级而非块级</strong>：目前判&quot;命中哪篇文档&quot;，未判&quot;命中正确章节&quot;；</li><li><strong>未覆盖多轮对话</strong>：当前只评测单轮问答；</li><li><strong>Hit@5 已饱和</strong>：100% 后该指标失去区分度，优化要看 Hit@1 / MRR / Recall@5。</li></ul><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./03-server-rag.html">03 · 后端与 RAG 检索</a> —— 被评估的检索链路</li><li><a href="./05-decisions.html">05 · 设计决策与踩坑</a> —— 提高准确性的手段与踩坑</li><li><a href="./../ai-agent/rag/rag-vs-finetuning.html">RAG vs 微调</a> —— 为什么选 RAG</li></ul>`,92)])])}const k=s(n,[["render",o]]);export{c as __pageData,k as default};
